1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
11	type Project = {
12	  id: number;
13	  name: string;
14	  clientId: number;
15	  clientName: string;
16	  archived: boolean;
17	  status: ProjectStatus;
18	};
19	type Invoice = {
20	  id: number;
21	  projectId: number;
22	  amount: number;
23	  amountDue: number;
24	  status: string;
25	  issuedDate: string;
26	  dueDate: string;
27	};
28	type Task = { id: number; projectId: number; title: string; done: boolean };
29	type Tag = { id: number; name: string };
30	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
31	
32	type LineItem = {
33	  id: number;
34	  invoiceId: number;
35	  description: string;
36	  qty: number;
37	  unitPrice: number;
38	};
39	
40	type Payment = { id: number; invoiceId: number; amount: number; date: string };
41	
42	function money(amount: number): string {
43	  return `$${Number(amount).toFixed(2)}`;
44	}
45	
46	// One charge line while it is being edited on screen: the fields are held as raw strings so the
47	// inputs stay controlled and the total can recompute live as they change.
48	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
49	
50	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
51	// many, price each), the total worked out for you, and a form to add another line. Each line can be
52	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
53	// own line-item state, scoped to the one invoice it is showing.
54	function InvoiceDetail({
55	  invoiceId,
56	  onChange,
57	  onClose,
58	}: {
59	  invoiceId: number;
60	  onChange: () => void;
61	  onClose: () => void;
62	}) {
63	  const [items, setItems] = useState<EditItem[]>([]);
64	  const [description, setDescription] = useState('');
65	  const [qty, setQty] = useState('');
66	  const [unitPrice, setUnitPrice] = useState('');
67	  const [payments, setPayments] = useState<Payment[]>([]);
68	  const [paymentAmount, setPaymentAmount] = useState('');
69	  const [paymentDate, setPaymentDate] = useState('');
70	  const [status, setStatus] = useState('');
71	
72	  // The status is worked out from the payments recorded against the invoice, so re-read it whenever
73	  // a payment is added rather than flipping it by hand.
74	  async function loadStatus() {
75	    const res = await fetch(`/api/invoices/${invoiceId}`);
76	    const inv: Invoice = await res.json();
77	    setStatus(inv.status);
78	  }
79	
80	  async function load() {
81	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
82	    const rows: LineItem[] = await res.json();
83	    setItems(
84	      rows.map((li) => ({
85	        id: li.id,
86	        description: li.description,
87	        qty: String(li.qty),
88	        unitPrice: String(li.unitPrice),
89	      })),
90	    );
91	  }
92	
93	  async function loadPayments() {
94	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
95	    setPayments(await res.json());
96	  }
97	
98	  async function submitPayment(e: React.FormEvent) {
99	    e.preventDefault();
100	    const value = Number(paymentAmount);
101	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
102	      return;
103	    }
104	    if (paymentDate.trim() === '') {
105	      return;
106	    }
107	    await fetch(`/api/invoices/${invoiceId}/payments`, {
108	      method: 'POST',
109	      headers: { 'Content-Type': 'application/json' },
110	      body: JSON.stringify({ amount: value, date: paymentDate }),
111	    });
112	    setPaymentAmount('');
113	    setPaymentDate('');
114	    await loadPayments();
115	    await loadStatus();
116	    onChange();
117	  }
118	
119	  useEffect(() => {
120	    void load();
121	    void loadPayments();
122	    void loadStatus();
123	  }, [invoiceId]);
124	
125	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
126	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
127	  }
128	
129	  function amountOf(li: EditItem): number {
130	    const line = Number(li.qty) * Number(li.unitPrice);
131	    return Number.isFinite(line) ? line : 0;
132	  }
133	
134	  async function save(li: EditItem) {
135	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
136	      return;
137	    }
138	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
139	      method: 'POST',
140	      headers: { 'Content-Type': 'application/json' },
141	      body: JSON.stringify({
142	        description: li.description,
143	        qty: Number(li.qty),
144	        unitPrice: Number(li.unitPrice),
145	      }),
146	    });
147	    await load();
148	    onChange();
149	  }
150	
151	  async function remove(id: number) {
152	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
153	    await load();
154	    onChange();
155	  }
156	
157	  async function submit(e: React.FormEvent) {
158	    e.preventDefault();
159	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
160	      return;
161	    }
162	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
163	      method: 'POST',
164	      headers: { 'Content-Type': 'application/json' },
165	      body: JSON.stringify({
166	        description,
167	        qty: Number(qty),
168	        unitPrice: Number(unitPrice),
169	      }),
170	    });
171	    setDescription('');
172	    setQty('');
173	    setUnitPrice('');
174	    await load();
175	    onChange();
176	  }
177	
178	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
179	
180	  return (
181	    <section data-testid="invoice-detail">
182	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
183	        Back to invoices
184	      </button>
185	
186	      <p data-testid="invoice-status">{status}</p>
187	
188	      <table data-testid="invoice-lineitems-table">
189	        <tbody>
190	          {items.map((li) => (
191	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
192	              <td>
193	                <input
194	                  data-testid="lineitem-description"
195	                  value={li.description}
196	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
197	                />
198	              </td>
199	              <td>
200	                <input
201	                  data-testid="lineitem-qty"
202	                  value={li.qty}
203	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
204	                />
205	              </td>
206	              <td>
207	                <input
208	                  data-testid="lineitem-unitprice"
209	                  value={li.unitPrice}
210	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
211	                />
212	              </td>
213	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
214	              <td>
215	                <button
216	                  data-testid={`lineitem-save-${li.id}`}
217	                  type="button"
218	                  onClick={() => save(li)}
219	                >
220	                  Save
221	                </button>
222	                <button
223	                  data-testid={`lineitem-remove-${li.id}`}
224	                  type="button"
225	                  onClick={() => remove(li.id)}
226	                >
227	                  Remove
228	                </button>
229	              </td>
230	            </tr>
231	          ))}
232	        </tbody>
233	      </table>
234	
235	      <p data-testid="invoice-amount">{money(total)}</p>
236	
237	      <form data-testid="lineitem-form" onSubmit={submit}>
238	        <input
239	          data-testid="lineitem-form-description"
240	          placeholder="Description"
241	          value={description}
242	          onChange={(e) => setDescription(e.target.value)}
243	        />
244	        <input
245	          data-testid="lineitem-form-qty"
246	          placeholder="How many"
247	          value={qty}
248	          onChange={(e) => setQty(e.target.value)}
249	        />
250	        <input
251	          data-testid="lineitem-form-unitprice"
252	          placeholder="Price each"
253	          value={unitPrice}
254	          onChange={(e) => setUnitPrice(e.target.value)}
255	        />
256	        <button data-testid="lineitem-form-submit" type="submit">
257	          Add line item
258	        </button>
259	      </form>
260	
261	      <table data-testid="invoice-payments-table">
262	        <tbody>
263	          {payments.map((p) => (
264	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
265	              <td data-testid="payment-amount">{money(p.amount)}</td>
266	              <td data-testid="payment-date">{p.date}</td>
267	            </tr>
268	          ))}
269	        </tbody>
270	      </table>
271	
272	      <form data-testid="payment-form" onSubmit={submitPayment}>
273	        <input
274	          data-testid="payment-form-amount"
275	          placeholder="Amount paid"
276	          value={paymentAmount}
277	          onChange={(e) => setPaymentAmount(e.target.value)}
278	        />
279	        <input
280	          data-testid="payment-form-date"
281	          type="date"
282	          value={paymentDate}
283	          onChange={(e) => setPaymentDate(e.target.value)}
284	        />
285	        <button data-testid="payment-form-submit" type="submit">
286	          Record payment
287	        </button>
288	      </form>
289	    </section>
290	  );
291	}
292	
293	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
294	// own invoice state, scoped to the one project it is showing.
295	function ProjectDetail({ project }: { project: Project }) {
296	  const [invoices, setInvoices] = useState<Invoice[]>([]);
297	  const [tasks, setTasks] = useState<Task[]>([]);
298	  const [tags, setTags] = useState<Tag[]>([]);
299	  const [allTags, setAllTags] = useState<Tag[]>([]);
300	  const [tagToAdd, setTagToAdd] = useState('');
301	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
302	  const [amount, setAmount] = useState('');
303	  const [amountError, setAmountError] = useState('');
304	  const [sortByDue, setSortByDue] = useState(false);
305	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
306	  const [notes, setNotes] = useState<Note[]>([]);
307	  const [noteText, setNoteText] = useState('');
308	
309	  async function load() {
310	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
311	    setInvoices(await res.json());
312	  }
313	
314	  async function loadNotes() {
315	    const res = await fetch(`/api/notes?targetType=project&targetId=${project.id}`);
316	    setNotes(await res.json());
317	  }
318	
319	  async function submitNote(e: React.FormEvent) {
320	    e.preventDefault();
321	    if (!noteText.trim()) {
322	      return;
323	    }
324	    await fetch('/api/notes', {
325	      method: 'POST',
326	      headers: { 'Content-Type': 'application/json' },
327	      body: JSON.stringify({ targetType: 'project', targetId: project.id, text: noteText }),
328	    });
329	    setNoteText('');
330	    await loadNotes();
331	  }
332	
333	  async function loadTasks() {
334	    const res = await fetch(`/api/tasks?projectId=${project.id}`);
335	    setTasks(await res.json());
336	  }
337	
338	  async function loadTags() {
339	    const [mine, all] = await Promise.all([
340	      fetch(`/api/projects/${project.id}/tags`).then((r) => r.json()),
341	      fetch('/api/tags').then((r) => r.json()),
342	    ]);
343	    setTags(mine);
344	    setAllTags(all);
345	  }
346	
347	  useEffect(() => {
348	    void load();
349	    void loadTasks();
350	    void loadTags();
351	    void loadNotes();
352	  }, [project.id]);
353	
354	  async function toggleTask(id: number) {
355	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
356	    await loadTasks();
357	  }
358	
359	  async function addTag(e: React.FormEvent) {
360	    e.preventDefault();
361	    if (!tagToAdd) {
362	      return;
363	    }
364	    await fetch(`/api/projects/${project.id}/tags`, {
365	      method: 'POST',
366	      headers: { 'Content-Type': 'application/json' },
367	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
368	    });
369	    setTagToAdd('');
370	    await loadTags();
371	  }
372	
373	  async function removeTag(id: number) {
374	    await fetch(`/api/projects/${project.id}/tags/${id}/remove`, { method: 'POST' });
375	    await loadTags();
376	  }
377	
378	  async function submit(e: React.FormEvent) {
379	    e.preventDefault();
380	    const value = Number(amount);
381	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
382	      setAmountError('Amount must be more than zero');
383	      return;
384	    }
385	    setAmountError('');
386	    await fetch('/api/invoices', {
387	      method: 'POST',
388	      headers: { 'Content-Type': 'application/json' },
389	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
390	    });
391	    setAmount('');
392	    await load();
393	  }
394	
395	  async function send(id: number) {
396	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
397	    await load();
398	  }
399	
400	  async function pay(id: number) {
401	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
402	    await load();
403	  }
404	
405	  const shownTasks = tasks.filter((t) =>
406	    taskFilter === 'OPEN' ? !t.done : taskFilter === 'DONE' ? t.done : true,
407	  );
408	
409	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
410	  const shownInvoices = sortByDue
411	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
412	    : invoices;
413	
414	  return (
415	    <section data-testid="project-detail">
416	      <h2 data-testid="project-detail-name">{project.name}</h2>
417	
418	      <div data-testid="project-tags">
419	        {tags.map((tag) => (
420	          <span key={tag.id}>
421	            <span data-testid={`project-tag-${tag.id}`}>{tag.name}</span>
