1	package net.officefloor.hq.app;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Map;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 *
19	 * <p>{@link #seed} is a plain sequence of one {@code seed*} method per entity. Teaching a new entity
20	 * to the harness is therefore additive: add its {@code seed*} method, call it from {@link #seed},
21	 * and add its {@code TRUNCATE} to {@link #reset} — no existing entity's code is touched.
22	 */
23	@Profile("harness")
24	@RestController
25	@RequestMapping("/__test__")
26	public class TestSupportController {
27	
28	    private final Audit audit;
29	    private final JdbcTemplate jdbc;
30	
31	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
32	        this.audit = audit;
33	        this.jdbc = jdbc;
34	    }
35	
36	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
37	    @PostMapping("/reset")
38	    public void reset() {
39	        audit.clear();
40	        // Referential integrity is dropped for the duration so the tables can be truncated (and
41	        // their identity counters restarted) regardless of FK order (e.g. projects -> clients).
42	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
43	        for (String table : List.of("notes", "project_tags", "tags", "tasks", "payments",
44	                "line_items", "invoices", "contacts", "projects", "clients")) {
45	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
46	        }
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
48	    }
49	
50	    /** Insert the fixture a spec needs; each entity is seeded by its own {@code seed*} method. */
51	    @PostMapping("/seed")
52	    public void seed(@RequestBody Map<String, Object> fixture) {
53	        seedClients(fixture);
54	        seedProjects(fixture);
55	        seedContacts(fixture);
56	        seedInvoices(fixture);
57	        seedPayments(fixture);
58	        seedTasks(fixture);
59	        seedTags(fixture);
60	        seedNotes(fixture);
61	        seedProjectTags(fixture);
62	    }
63	
64	    private void seedClients(Map<String, Object> fixture) {
65	        for (Map<String, Object> c : rows(fixture, "clients")) {
66	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
67	                    id(c, "id"), c.get("name"), c.get("email"));
68	        }
69	    }
70	
71	    private void seedProjects(Map<String, Object> fixture) {
72	        for (Map<String, Object> p : rows(fixture, "projects")) {
73	            // status defaults to ACTIVE so a fixture that omits it gets an active project; archived
74	            // defaults to FALSE (the table default) unless the fixture pins it.
75	            new Insert("projects")
76	                    .set("id", id(p, "id"))
77	                    .set("name", p.get("name"))
78	                    .set("client_id", id(p, "clientId"))
79	                    .set("status", p.get("status") == null ? "ACTIVE" : p.get("status").toString())
80	                    .setIfPresent("archived", p.get("archived"))
81	                    .run();
82	        }
83	    }
84	
85	    private void seedContacts(Map<String, Object> fixture) {
86	        for (Map<String, Object> ct : rows(fixture, "contacts")) {
87	            jdbc.update(
88	                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
89	                    id(ct, "id"), id(ct, "clientId"), ct.get("name"), ct.get("email"),
90	                    ct.get("role"));
91	        }
92	    }
93	
94	    private void seedInvoices(Map<String, Object> fixture) {
95	        for (Map<String, Object> in : rows(fixture, "invoices")) {
96	            // Insert only the columns the fixture supplies, so the table's own defaults apply when a
97	            // fixture omits them (a plain null would trip the NOT NULL columns). status defaults to
98	            // DRAFT and amount defaults to 0 — an invoice's amount is derived from its line items,
99	            // so fixtures list lineItems rather than a single typed amount.
100	            new Insert("invoices")
101	                    .set("id", id(in, "id"))
102	                    .set("project_id", id(in, "projectId"))
